function e($x){return htmlspecialchars((string)$x,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function route($p,$q=[]){return '/?'.http_build_query(['p'=>$p]+$q);}
function redirect($p){header('Location: '.route($p),true,303);exit;}
function token(){return '<input type="hidden" name="csrf" value="'.e($_SESSION['csrf']).'">';}
function guard(){if(!isset($_SESSION['uid']))redirect('login');}
function query(PDO $db,$sql,$args=[]){$q=$db->prepare($sql);$q->execute($args);return $q;}
