if(!(int)$db->query('SELECT COUNT(*) FROM categories')->fetchColumn()){
 foreach([['Công nghệ','cong-nghe'],['Giáo dục','giao-duc'],['Khoa học','khoa-hoc'],['Đời sống','doi-song'],['Sự kiện','su-kien']] as $row)query($db,'INSERT INTO categories(name,slug) VALUES(?,?)',$row);
 $seed=[
 [1,'Công nghệ số và xu hướng phát triển ứng dụng web','Những nền tảng công nghệ quan trọng trong phát triển web hiện đại.','Trong kỷ nguyên số, ứng dụng web là nền tảng quan trọng để cung cấp thông tin và dịch vụ. Docker giúp đóng gói ứng dụng thành container nhất quán. Nginx hỗ trợ reverse proxy và các security headers, trong khi Prometheus và Grafana giúp quan sát sức khỏe hệ thống.'],
 [2,'Sinh viên công nghệ thông tin tăng cường kỹ năng thực hành','Thực hành quản trị hệ thống giúp kết nối kiến thức với thực tiễn.','Sinh viên nên kết hợp kiến thức cơ sở dữ liệu, Linux, mạng máy tính và phát triển phần mềm. Một dự án triển khai hoàn chỉnh gồm mã nguồn, cấu hình và tài liệu hướng dẫn vận hành.'],
 [3,'Vai trò của hệ thống giám sát trong vận hành phần mềm','Theo dõi máy chủ, container và cơ sở dữ liệu với công cụ mã nguồn mở.','Prometheus thu thập metrics từ exporter. Grafana hiển thị dashboard theo thời gian. Loki và Promtail giúp thu thập và truy vấn log bằng LogQL.'],
 [4,'Bảo vệ tài khoản và dữ liệu trong môi trường số','Các biện pháp bảo mật đơn giản nhưng cần thiết khi sử dụng dịch vụ web.','Cần sử dụng mật khẩu mạnh, giới hạn quyền truy cập, chống lộ thông tin bí mật và kiểm tra bản cập nhật hệ thống. Phân tách mạng Docker giúp giảm khả năng truy cập trái phép đến cơ sở dữ liệu.'],
 [5,'Giới thiệu cổng thông tin ICT NEWS','Website tin tức phục vụ đề tài thực hành số 19.','Hệ thống mẫu có các chức năng xem tin, tìm kiếm, phân loại nội dung và quản trị bài viết. Đây là dữ liệu minh họa được tạo tự động khi ứng dụng khởi chạy lần đầu.']];
 foreach($seed as $r)query($db,'INSERT INTO posts(category_id,title,summary,body) VALUES(?,?,?,?)',$r);
}
if(!(int)$db->query('SELECT COUNT(*) FROM admins')->fetchColumn())query($db,'INSERT INTO admins(email,password) VALUES(?,?)',[getenv('ADMIN_EMAIL'),password_hash(getenv('ADMIN_PASSWORD'),PASSWORD_DEFAULT)]);
}catch(Throwable $ex){error_log('DB startup failure: '.$ex->getMessage());http_response_code(503);exit('Dịch vụ đang khởi tạo. Vui lòng thử lại sau.');}
