 if($page==='logout'){$_SESSION=[];session_regenerate_id(true);redirect('home');}
 if($page==='save'){
 guard();$id=(int)($_POST['id']??0);$cat=(int)($_POST['category_id']??0);$title=trim($_POST['title']??'');$summary=trim($_POST['summary']??'');$body=trim($_POST['body']??'');$img=trim($_POST['image_url']??'');$pub=isset($_POST['published'])?1:0;
 if(!$title||!$summary||!$body||!$cat||strlen($title)>240||strlen($summary)>500||strlen($img)>500||($img&&!filter_var($img,FILTER_VALIDATE_URL)))$error='Dữ liệu không hợp lệ. Hãy điền đủ nội dung và kiểm tra URL ảnh.';
 else{if($id)query($db,'UPDATE posts SET category_id=?,title=?,summary=?,body=?,image_url=?,published=? WHERE id=?',[$cat,$title,$summary,$body,$img,$pub,$id]);else query($db,'INSERT INTO posts(category_id,title,summary,body,image_url,published) VALUES(?,?,?,?,?,?)',[$cat,$title,$summary,$body,$img,$pub]);redirect('admin');}
 }
 if($page==='delete'){guard();query($db,'DELETE FROM posts WHERE id=?',[(int)($_POST['id']??0)]);redirect('admin');}
 if($page==='addcat'){guard();$name=trim($_POST['name']??'');$slug=trim($_POST['slug']??'');if(!$name||strlen($name)>100||!preg_match('/^[a-z0-9-]{2,120}$/',$slug))$error='Tên danh mục hoặc slug không hợp lệ.';else{try{query($db,'INSERT INTO categories(name,slug) VALUES(?,?)',[$name,$slug]);redirect('cats');}catch(Throwable $ex){$error='Slug đã tồn tại.';}}}
 if($page==='delcat'){guard();try{query($db,'DELETE FROM categories WHERE id=?',[(int)($_POST['id']??0)]);redirect('cats');}catch(Throwable $ex){$error='Không thể xóa danh mục đang chứa bài viết.';}}
}
$cats=$db->query('SELECT * FROM categories ORDER BY id')->fetchAll();
