if($page==='home'){
 $args=[];$w='p.published=1';if(!empty($_GET['cat'])){$w.=' AND c.slug=?';$args[]=$_GET['cat'];}if(!empty($_GET['q'])){$w.=' AND (p.title LIKE ? OR p.summary LIKE ?)';$args[]='%'.$_GET['q'].'%';$args[]='%'.$_GET['q'].'%';}
 $posts=query($db,"SELECT p.*,c.name category FROM posts p JOIN categories c ON c.id=p.category_id WHERE $w ORDER BY p.id DESC LIMIT 60",$args)->fetchAll();top('Tin mới nhất');?><section class="hero"><div><div class="overline">CỔNG THÔNG TIN ICT NEWS</div><h1>Góc nhìn mới.<br>Thông tin mỗi ngày.</h1><p>Cập nhật kiến thức công nghệ, khoa học, giáo dục và đời sống.</p><a class="button white" href="#news">Khám phá tin tức →</a></div><div class="bubble">NEWS<small>24/7</small></div></section><section class="heading" id="news"><div><div class="overline">BẢN TIN HÔM NAY</div><h2>Tin tức mới cập nhật</h2></div><form><input name="q" aria-label="Tìm kiếm" placeholder="Tìm kiếm bài viết..." value="<?=e($_GET['q']??'')?>"><button>Tìm kiếm</button></form></section><div class="chips"><a href="/">Tất cả</a><?php foreach($cats as $c):?><a href="<?=e(route('home',['cat'=>$c['slug']]))?>"><?=e($c['name'])?></a><?php endforeach;?></div><div class="grid"><?php foreach($posts as $p):?><article class="card"><a class="cardimage" href="<?=e(route('post',['id'=>$p['id']]))?>"><?php if($p['image_url']):?><img src="<?=e($p['image_url'])?>" alt="Ảnh bài viết" loading="lazy"><?php else:?><small><?=e($p['category'])?></small><strong>ICT<br>NEWS</strong><?php endif;?></a><div class="cardcontent"><span class="tag"><?=e($p['category'])?></span> <span class="muted"><?=e(date('d/m/Y',strtotime($p['created_at'])))?></span><h3><a href="<?=e(route('post',['id'=>$p['id']]))?>"><?=e($p['title'])?></a></h3><p><?=e($p['summary'])?></p><a class="more" href="<?=e(route('post',['id'=>$p['id']]))?>">Đọc bài viết →</a></div></article><?php endforeach;?></div><?php if(!$posts):?><p class="empty">Không tìm thấy bài viết phù hợp.</p><?php endif;bottom();
}elseif($page==='post'){$p=query($db,'SELECT p.*,c.name category FROM posts p JOIN categories c ON c.id=p.category_id WHERE p.id=?'.(isset($_SESSION['uid'])?'':' AND p.published=1'),[(int)($_GET['id']??0)])->fetch();if(!$p){http_response_code(404);top('404');echo '<p>Không tìm thấy bài viết.</p>';bottom();exit;}top($p['title']);?><article class="story"><span class="tag"><?=e($p['category'])?></span> <span class="muted"><?=e($p['created_at'])?></span><h1><?=e($p['title'])?></h1><p class="lead"><?=e($p['summary'])?></p><?php if($p['image_url']):?><img class="storyimage" src="<?=e($p['image_url'])?>" alt="Ảnh bài viết"><?php endif;?><div class="storybody"><?=nl2br(e($p['body']))?></div><a class="button" href="/">← Quay lại</a></article><?php bottom();
