}elseif(in_array($page,['edit','save'],true)){guard();$id=(int)($_GET['id']??$_POST['id']??0);$p=['id'=>0,'category_id'=>$cats[0]['id'],'title'=>'','summary'=>'','body'=>'','image_url'=>'','published'=>1];if($id)$p=query($db,'SELECT * FROM posts WHERE id=?',[$id])->fetch()?:$p;if($error)$p=array_merge($p,$_POST);top('Biên tập bài viết');?><div class="panel"><h1><?=$id?'Chỉnh sửa bài viết':'Đăng bài viết mới'?></h1><?php if($error):?><p class="alert"><?=e($error)?></p><?php endif;?><form method="post" action="<?=e(route('save'))?>"><?=token()?><input type="hidden" name="id" value="<?=e($id)?>"><label>Tiêu đề<input name="title" maxlength="240" required value="<?=e($p['title'])?>"></label><label>Danh mục<select name="category_id"><?php foreach($cats as $c):?><option value="<?=e($c['id'])?>" <?=((int)$p['category_id']===(int)$c['id'])?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></label><label>Tóm tắt<textarea name="summary" rows="3" maxlength="500" required><?=e($p['summary'])?></textarea></label><label>Nội dung<textarea name="body" rows="12" required><?=e($p['body'])?></textarea></label><label>URL ảnh đại diện (không bắt buộc)<input type="url" name="image_url" maxlength="500" value="<?=e($p['image_url'])?>"></label><label><input type="checkbox" name="published" <?=!empty($p['published'])?'checked':''?>> Xuất bản công khai</label><div><button>Lưu bài viết</button> <a href="<?=e(route('admin'))?>">Hủy</a></div></form></div><?php bottom();
